package com.example.project.service;
import com.example.project.dto.*;import com.example.project.entity.SiteUser;import com.example.project.repository.SiteUserRepository;import org.springframework.stereotype.Service;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.Map;
@Service public class AuthService {private final SiteUserRepository repo;private final PasswordEncoder encoder;public AuthService(SiteUserRepository r,PasswordEncoder e){repo=r;encoder=e;}
public Map<String,Object> register(RegisterRequest r){String email=r.getEmail().trim().toLowerCase();if(repo.existsByEmail(email))throw new IllegalArgumentException("Email already registered");SiteUser u=new SiteUser();u.setName(r.getName().trim());u.setEmail(email);u.setPhone(r.getPhone().trim());u.setPasswordHash(encoder.encode(r.getPassword()));repo.save(u);return Map.of("message","Registration successful. You can now log in.","userId",u.getId());}
public Map<String,Object> login(LoginRequest r){SiteUser u=repo.findByEmail(r.getEmail().trim().toLowerCase()).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!encoder.matches(r.getPassword(),u.getPasswordHash()))throw new IllegalArgumentException("Invalid email or password");return Map.of("message","Login successful","userId",u.getId(),"name",u.getName());}}